// ===== GitHub-backed storage (shared by both sites). All data lives as JSON files in your PRIVATE GitHub repo. =====
class HttpErr extends Error { constructor(status, msg) { super(msg); this.status = status; } }
const GH_API = 'https://api.github.com';
const b64enc = (str) => { const b = new TextEncoder().encode(str); let s = ''; for (let i = 0; i < b.length; i += 0x8000) s += String.fromCharCode(...b.subarray(i, i + 0x8000)); return btoa(s); };
const b64dec = (s) => new TextDecoder().decode(Uint8Array.from(atob(s.replace(/\s/g, '')), (c) => c.charCodeAt(0)));
function ghHeaders(env, extra) {
  if (!env.GH_TOKEN || !env.GH_REPO) throw new HttpErr(500, 'Storage is not connected yet: set GH_TOKEN and GH_REPO in Cloudflare.');
  return { authorization: `Bearer ${env.GH_TOKEN}`, 'user-agent': 'dinesh-site', accept: 'application/vnd.github+json', 'x-github-api-version': '2022-11-28', ...extra };
}
const ghBranch = (env) => env.GH_BRANCH || 'main';
async function ghGet(env, path) {
  const r = await fetch(`${GH_API}/repos/${env.GH_REPO}/contents/${path}?ref=${ghBranch(env)}`, { headers: ghHeaders(env) });
  if (r.status === 404) return null;
  if (!r.ok) throw new HttpErr(502, `GitHub ${r.status}: could not read ${path} (check GH_TOKEN / GH_REPO).`);
  const j = await r.json();
  let content = j.content;
  if (!content) { const b = await fetch(`${GH_API}/repos/${env.GH_REPO}/git/blobs/${j.sha}`, { headers: ghHeaders(env) }); content = (await b.json()).content; }
  return { text: b64dec(content), sha: j.sha };
}
async function ghPut(env, path, b64, sha, msg) {
  const r = await fetch(`${GH_API}/repos/${env.GH_REPO}/contents/${path}`, { method: 'PUT', headers: ghHeaders(env, { 'content-type': 'application/json' }), body: JSON.stringify({ message: msg, content: b64, branch: ghBranch(env), ...(sha ? { sha } : {}) }) });
  if (r.ok) return (await r.json()).content.sha;
  if (r.status === 409 || r.status === 422) return 'CONFLICT';
  const e = await r.json().catch(() => ({}));
  throw new HttpErr(502, `GitHub ${r.status}: ${r.status === 401 ? 'GH_TOKEN is wrong or expired.' : r.status === 404 ? 'Repo not found or token has no access (check GH_REPO and token permissions).' : e.message || 'error'}`);
}
const DEFAULT_SETTINGS = { about_name: 'Dinesh Rajbanshi', about_title: 'Modern farming educator & developer', about_bio: 'Write about yourself from the admin site > Profile.', about_photo: '', contact_email: 'dinesh.fm@gmail.com', contact_phone: '', contact_video: '', site_tagline: 'Practical knowledge for the modern farmer', pay_info: 'We will contact you on your phone to confirm your seat and share payment details.' };
function defaults(name) {
  if (name === 'settings') return { ...DEFAULT_SETTINGS };
  if (name === 'articles') {
    const t = Date.now();
    return { next_id: 2, items: [{ id: 1, title: 'Welcome to my website', subtitle: 'Articles, online classes and a community for farmers who want to grow smarter.', category: 'Announcement', body: 'This is a sample article so your site is not empty. Delete or edit it from the admin site.\n\n## What you will find here\n\n- Professional articles on crops, soil, water and technology\n- Online classes you can book in a minute\n- A discussion space where every farmer can ask and answer\n\n> Good farming is a conversation between people, soil and season.', highlights: 'Read and listen to every article\nBook online classes\nAsk the community', img1: '', img1_cap: '', img2: '', img2_cap: '', video: '', lang: 'en-US', author: 'Dinesh Rajbanshi', published: 1, created_at: t, updated_at: t }] };
  }
  return { next_id: 1, items: [] };
}
const STORE = new Map(); let STORE_TTL = 15000;
async function loadFile(env, name, fresh) {
  const c = STORE.get(name);
  if (!fresh && c && Date.now() - c.t < STORE_TTL) return c;
  const f = await ghGet(env, `data/${name}.json`);
  const e = { t: Date.now(), sha: f ? f.sha : null, data: f ? JSON.parse(f.text) : defaults(name) };
  STORE.set(name, e); return e;
}
const readData = async (env, name, fresh) => (await loadFile(env, name, fresh)).data;
// Safe read-modify-write: if two people save at the same moment, GitHub rejects the second and we re-apply on fresh data.
async function mutate(env, name, fn) {
  for (let i = 0; i < 6; i++) {
    const e = await loadFile(env, name, true);
    const data = structuredClone(e.data);
    const out = await fn(data);
    const sha = await ghPut(env, `data/${name}.json`, b64enc(JSON.stringify(data)), e.sha, 'Update ' + name);
    if (sha !== 'CONFLICT') { STORE.set(name, { t: Date.now(), sha, data }); return out; }
    STORE.delete(name);
    await new Promise((r) => setTimeout(r, 80 + Math.random() * 200));
  }
  throw new HttpErr(503, 'The site is busy. Please try again in a moment.');
}
const HITS = new Map();
function tooFast(key, max, windowMs) {
  const now = Date.now(), arr = (HITS.get(key) || []).filter((t) => now - t < windowMs);
  if (arr.length >= max) { HITS.set(key, arr); return true; }
  arr.push(now); HITS.set(key, arr);
  if (HITS.size > 5000) HITS.clear();
  return false;
}
async function ghImage(env, p, ttl) {
  const path = p.slice(5);
  if (!/^[\w\-\/.]+$/.test(path) || path.includes('..')) return new Response('Not found', { status: 404 });
  const r = await fetch(`${GH_API}/repos/${env.GH_REPO}/contents/img/${path}?ref=${ghBranch(env)}`, { headers: ghHeaders(env, { accept: 'application/vnd.github.raw+json' }), cf: { cacheEverything: true, cacheTtl: ttl } });
  if (!r.ok) return new Response('Not found', { status: 404 });
  const type = /\.png$/i.test(path) ? 'image/png' : /\.webp$/i.test(path) ? 'image/webp' : 'image/jpeg';
  return new Response(r.body, { headers: { 'content-type': type, 'cache-control': `public, max-age=${ttl}`, 'x-content-type-options': 'nosniff' } });
}
const errResponse = (J, e) => (e instanceof HttpErr ? J({ error: e.message }, e.status) : J({ error: 'Server error. Please try again.' }, 500));
// ===== end storage =====

// Developer admin worker (separate Cloudflare Pages project). No database: everything is stored in your private GitHub repo.
// Needs: ADMIN_PASSWORD (secret), GH_TOKEN (secret), GH_REPO ("username/farming-data"); optional GH_BRANCH.

const J = (d, s = 200, h = {}) =>
  new Response(JSON.stringify(d), { status: s, headers: { 'content-type': 'application/json; charset=utf-8', 'cache-control': 'no-store', 'x-content-type-options': 'nosniff', 'x-robots-tag': 'noindex, nofollow', ...h } });
const enc = new TextEncoder();
const now = () => Date.now();
const body = async (req) => { try { return await req.json(); } catch { return {}; } };
const byNew = (a, b) => b.created_at - a.created_at;

async function hmac(key, msg) {
  const k = await crypto.subtle.importKey('raw', enc.encode(key), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']);
  const s = await crypto.subtle.sign('HMAC', k, enc.encode(msg));
  return [...new Uint8Array(s)].map((b) => b.toString(16).padStart(2, '0')).join('');
}
function safeEq(a, b) { if (a.length !== b.length) return false; let r = 0; for (let i = 0; i < a.length; i++) r |= a.charCodeAt(i) ^ b.charCodeAt(i); return r === 0; }
async function makeToken(env) { const exp = now() + 7 * 864e5; return exp + '.' + (await hmac(env.ADMIN_PASSWORD, 'session|' + exp)); }
async function isAuthed(req, env) {
  if (!env.ADMIN_PASSWORD) return false;
  const m = (req.headers.get('cookie') || '').match(/(?:^|;\s*)adm=([^;]+)/);
  if (!m) return false;
  const [exp, sig] = m[1].split('.');
  if (!exp || !sig || Number(exp) < now()) return false;
  return safeEq(sig, await hmac(env.ADMIN_PASSWORD, 'session|' + exp));
}

const TABLES = {
  articles: {
    cols: { title: 200, subtitle: 400, category: 60, body: 80000, highlights: 2000, img1: 300, img1_cap: 300, img2: 300, img2_cap: 300, video: 300, lang: 10, author: 80, published: 'bool' },
    req: ['title', 'body'],
    blank: { subtitle: '', category: 'General', highlights: '', img1: '', img1_cap: '', img2: '', img2_cap: '', video: '', lang: 'en-US', author: '', published: 1 },
  },
  classes: {
    cols: { title: 200, description: 5000, price: 'num', currency: 8, schedule: 200, duration: 100, mode: 60, seats: 'int', img: 300, active: 'bool' },
    req: ['title'],
    blank: { description: '', price: 0, currency: 'NPR', schedule: '', duration: '', mode: 'Online class', seats: 0, img: '', active: 1 },
  },
};
const SETTING_KEYS = { about_name: 100, about_title: 200, about_bio: 8000, about_photo: 300, contact_email: 120, contact_phone: 30, contact_video: 300, site_tagline: 200, pay_info: 2000 };

function clean(spec, b, partial) {
  const out = {};
  for (const [c, t] of Object.entries(spec.cols)) {
    if (!(c in b)) continue;
    let v = b[c];
    if (t === 'bool') v = v ? 1 : 0;
    else if (t === 'num') v = Math.max(0, Number(v) || 0);
    else if (t === 'int') v = Math.max(0, Math.floor(Number(v) || 0));
    else {
      v = String(v ?? '').replace(/\u0000/g, '').trim().slice(0, t);
      if (['img1', 'img2', 'img'].includes(c) && v && !/^(\/img\/|https:\/\/)/.test(v)) v = '';
      if (c === 'video' && v && !/^https?:\/\//.test(v)) v = '';
    }
    out[c] = v;
  }
  if (!partial) for (const r of spec.req) if (!out[r]) throw new HttpErr(400, `"${r}" is required.`);
  return out;
}

const __worker = {
  async fetch(req, env) {
    const url = new URL(req.url);
    const p = url.pathname;
    try {
      if (p.startsWith('/api/')) return await api(req, env, p);
      if (p.startsWith('/img/')) return await ghImage(env, p, 3600);
      const r = await env.ASSETS.fetch(req);
      const h = new Headers(r.headers); h.set('x-robots-tag', 'noindex, nofollow');
      return new Response(r.body, { status: r.status, headers: h });
    } catch (e) {
      return errResponse(J, e);
    }
  },
};

STORE_TTL = 0; // admin always sees the latest data
const ATTEMPTS = new Map();

async function api(req, env, p) {
  const method = req.method;

  if (p === '/api/login' && method === 'POST') {
    if (!env.ADMIN_PASSWORD) return J({ error: 'ADMIN_PASSWORD is not set in Cloudflare yet (see setup guide).' }, 500);
    const ip = req.headers.get('CF-Connecting-IP') || 'local';
    const recent = (ATTEMPTS.get(ip) || []).filter((t) => now() - t < 15 * 60000);
    if (recent.length >= 6) return J({ error: 'Too many wrong attempts. Try again in 15 minutes.' }, 429);
    const b = await body(req);
    const a = await hmac('cmp', String(b.password || '')), c = await hmac('cmp', env.ADMIN_PASSWORD);
    if (!safeEq(a, c)) {
      recent.push(now()); ATTEMPTS.set(ip, recent);
      await new Promise((r) => setTimeout(r, 600));
      return J({ error: 'Wrong password.' }, 401);
    }
    ATTEMPTS.delete(ip);
    return J({ ok: true }, 200, { 'set-cookie': `adm=${await makeToken(env)}; Path=/; HttpOnly; Secure; SameSite=Strict; Max-Age=604800` });
  }
  if (p === '/api/logout') return J({ ok: true }, 200, { 'set-cookie': 'adm=; Path=/; HttpOnly; Secure; SameSite=Strict; Max-Age=0' });
  if (p === '/api/me') return J({ authed: await isAuthed(req, env) });

  if (!(await isAuthed(req, env))) return J({ error: 'Please log in.' }, 401);
  if (method !== 'GET' && req.headers.get('x-requested-with') !== 'admin') return J({ error: 'Bad request' }, 400);

  if (p === '/api/stats') {
    const [a, c, b, po, me] = await Promise.all(['articles', 'classes', 'bookings', 'posts', 'messages'].map((n) => readData(env, n)));
    return J({ articles: a.items.length, classes: c.items.length, bookings: b.items.length, pending: b.items.filter((x) => x.status === 'pending').length, posts: po.items.length, messages: me.items.filter((x) => !x.is_read).length, github: !!(env.GH_TOKEN && env.GH_REPO) });
  }

  // generic CRUD for articles + classes
  let m = p.match(/^\/api\/(articles|classes)(?:\/(\d+))?$/);
  if (m) {
    const t = m[1], id = m[2] ? Number(m[2]) : null, spec = TABLES[t];
    if (method === 'GET' && !id) {
      const d = await readData(env, t);
      if (t === 'articles') return J(d.items.slice().sort(byNew).map((a) => ({ id: a.id, title: a.title, category: a.category, published: a.published, created_at: a.created_at, updated_at: a.updated_at })));
      const bk = (await readData(env, 'bookings')).items;
      return J(d.items.slice().sort(byNew).map((c) => ({ ...c, booked: bk.filter((x) => x.class_id === c.id && x.status !== 'cancelled').length })));
    }
    if (method === 'GET' && id) {
      const r = (await readData(env, t)).items.find((x) => x.id === id);
      return r ? J(r) : J({ error: 'Not found' }, 404);
    }
    if (method === 'POST' && !id) {
      const out = clean(spec, await body(req), false), t0 = now();
      const nid = await mutate(env, t, (d) => { const i = d.next_id++; d.items.push({ id: i, ...spec.blank, ...out, created_at: t0, updated_at: t0 }); return i; });
      return J({ id: nid }, 201);
    }
    if (method === 'PUT' && id) {
      const out = clean(spec, await body(req), true);
      for (const r of spec.req) if (r in out && !out[r]) throw new HttpErr(400, `"${r}" is required.`);
      await mutate(env, t, (d) => { const it = d.items.find((x) => x.id === id); if (!it) throw new HttpErr(404, 'Not found'); Object.assign(it, out, { updated_at: now() }); });
      return J({ ok: true });
    }
    if (method === 'DELETE' && id) {
      await mutate(env, t, (d) => { d.items = d.items.filter((x) => x.id !== id); });
      if (t === 'classes') await mutate(env, 'bookings', (d) => { d.items = d.items.filter((x) => x.class_id !== id); });
      return J({ ok: true });
    }
  }

  if (p === '/api/bookings' && method === 'GET') {
    const [b, c] = await Promise.all([readData(env, 'bookings'), readData(env, 'classes')]);
    const title = new Map(c.items.map((x) => [x.id, x.title]));
    return J(b.items.slice().sort(byNew).slice(0, 500).map((x) => ({ id: x.id, name: x.name, email: x.email, phone: x.phone, note: x.note, status: x.status, created_at: x.created_at, class_title: title.get(x.class_id) || null })));
  }
  m = p.match(/^\/api\/bookings\/(\d+)$/);
  if (m && method === 'PUT') {
    const b = await body(req), id = Number(m[1]);
    if (!['pending', 'confirmed', 'cancelled'].includes(b.status)) return J({ error: 'Bad status' }, 400);
    await mutate(env, 'bookings', (d) => { const it = d.items.find((x) => x.id === id); if (it) it.status = b.status; });
    return J({ ok: true });
  }
  if (m && method === 'DELETE') { const id = Number(m[1]); await mutate(env, 'bookings', (d) => { d.items = d.items.filter((x) => x.id !== id); }); return J({ ok: true }); }

  if (p === '/api/posts' && method === 'GET') return J((await readData(env, 'posts')).items.slice().sort(byNew).slice(0, 300));
  m = p.match(/^\/api\/posts\/(\d+)$/);
  if (m && method === 'DELETE') { const id = Number(m[1]); await mutate(env, 'posts', (d) => { d.items = d.items.filter((x) => x.id !== id && x.parent_id !== id); }); return J({ ok: true }); }

  if (p === '/api/messages' && method === 'GET') return J((await readData(env, 'messages')).items.slice().sort(byNew).slice(0, 200));
  m = p.match(/^\/api\/messages\/(\d+)$/);
  if (m && method === 'PUT') { const id = Number(m[1]); await mutate(env, 'messages', (d) => { const it = d.items.find((x) => x.id === id); if (it) it.is_read = 1; }); return J({ ok: true }); }
  if (m && method === 'DELETE') { const id = Number(m[1]); await mutate(env, 'messages', (d) => { d.items = d.items.filter((x) => x.id !== id); }); return J({ ok: true }); }

  if (p === '/api/settings' && method === 'GET') return J(await readData(env, 'settings'));
  if (p === '/api/settings' && method === 'PUT') {
    const b = await body(req), upd = {};
    for (const [k, n] of Object.entries(SETTING_KEYS)) if (k in b) {
      let v = String(b[k] ?? '').trim().slice(0, n);
      if (k === 'about_photo' && v && !/^(\/img\/|https:\/\/)/.test(v)) v = '';
      upd[k] = v;
    }
    await mutate(env, 'settings', (d) => { Object.assign(d, upd); });
    return J({ ok: true });
  }

  // image upload -> committed to the GitHub repo (img/ folder)
  if (p === '/api/upload' && method === 'POST') {
    const b = await body(req);
    const data = String(b.data || '').replace(/^data:[^,]+,/, '');
    if (!data || data.length > 7_500_000) return J({ error: 'Image missing or too large (max about 5 MB).' }, 400);
    let head; try { head = atob(data.slice(0, 24)); } catch { return J({ error: 'Invalid image data.' }, 400); }
    const ext = head.startsWith('\xFF\xD8') ? 'jpg' : head.startsWith('\x89PNG') ? 'png' : head.startsWith('RIFF') && head.slice(8, 12) === 'WEBP' ? 'webp' : '';
    if (!ext) return J({ error: 'Only JPG, PNG or WebP images are allowed.' }, 400);
    const d = new Date(), id = crypto.randomUUID().replace(/-/g, '').slice(0, 14);
    const path = `${d.getUTCFullYear()}/${String(d.getUTCMonth() + 1).padStart(2, '0')}/${id}.${ext}`;
    const r = await ghPut(env, `img/${path}`, data, null, 'Upload image ' + path);
    if (r === 'CONFLICT') return J({ error: 'Upload clashed, please try again.' }, 409);
    return J({ url: '/img/' + path }, 201);
  }

  return J({ error: 'Not found' }, 404);
}

